const dec = (s) => {
  const b64 = (x) => { const c='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'; let o=[],b=0,n=0; for (const ch of x.replace(/=+$/,'')) { b=(b<<6)|c.indexOf(ch); n+=6; if(n>=8){ n-=8; o.push((b>>n)&255); b&=(1<<n)-1; } } return o; };
  return String(s||'').replace(/^\s*(From|Subject):\s*/i,'').replace(/=\?UTF-8\?([BQ])\?([^?]*)\?=\s*/gi,(m,e,t)=>{ try { return e.toUpperCase()==='B' ? decodeURIComponent(b64(t).map(x=>'%'+x.toString(16).padStart(2,'0')).join('')) : decodeURIComponent(t.replace(/_/g,' ').replace(/=([0-9A-F]{2})/gi,'%$1')); } catch(err){ return m; } }).replace(/\s+/g,' ').trim();
};
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const h = j.headers || {};
  const f = (j.from && j.from.value && j.from.value[0]) || {};
  const rawFrom = dec(h.from);
  const email = f.address || (rawFrom.match(/[^\s<>@"]+@[^\s<>@"]+\.[^\s<>@">]+/) || [''])[0];
  const name = f.name || rawFrom.replace(/<[^>]*>/, '').replace(/["']/g, '').trim();
  const asunto = dec(typeof j.subject === 'string' ? j.subject : h.subject) || '(sin asunto)';
  const cuerpo = String(j.text || j.snippet || '').replace(/\s+/g, ' ').trim().slice(0, 1500);
  out.push({ json: {
    sessionId: j.threadId || j.id,
    from_email: email,
    from_name: name,
    asunto: asunto,
    mensaje: 'Asunto: ' + asunto + '\n' + cuerpo
  }});
}
return out;
